def test_concept_id_from_relations_and_conceptrecid():
    record = ZenothecaRecord.model_validate(RECORD)
    assert record.concept_id == "6347574"
    assert record.metadata is not None
    assert record.metadata.concept_id == "6347574"
    bare = ZenothecaRecord.model_validate({"id": 1})
    assert bare.concept_id is None
    assert bare.metadata is None or bare.metadata.concept_id is None


